-- =====================================================================
-- fix_chain.sql — 全链路补全修复
-- 维护:地龙(DL-BOT)  2026-08-03
-- 1.价格精度 2.清假数据 3.unit_conversion 4.成本换算重算
-- 5.供应商关联 6.dish_recipe AI生成 7.成本卡 8.字段COMMENT
-- =====================================================================
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS=0;

-- ===== 1. 价格列精度修复(decimal(10,2)→decimal(15,8)保住0.03424真值) =====
ALTER TABLE ingredient_master MODIFY COLUMN unit_price decimal(15,8);
ALTER TABLE ingredient_cost_price MODIFY COLUMN purchase_price decimal(15,8);
ALTER TABLE ingredient_cost_price MODIFY COLUMN net_price_per_unit decimal(15,8);
ALTER TABLE ingredient_cost_price MODIFY COLUMN conversion_rate decimal(15,6);
ALTER TABLE purchase_order_detail MODIFY COLUMN unit_price decimal(15,8);
ALTER TABLE purchase_order_detail MODIFY COLUMN amount decimal(15,4);
ALTER TABLE purchase_receipt_detail MODIFY COLUMN unit_price decimal(15,8);
ALTER TABLE purchase_receipt_detail MODIFY COLUMN amount decimal(15,4);
ALTER TABLE dish_recipe MODIFY COLUMN unit_price decimal(15,8);
ALTER TABLE dish_recipe MODIFY COLUMN net_unit_price decimal(15,8);
ALTER TABLE dish_recipe MODIFY COLUMN total_cost decimal(15,4);
ALTER TABLE dish_cost_card_detail MODIFY COLUMN unit_price decimal(15,8);
ALTER TABLE dish_cost_card_detail MODIFY COLUMN cost_amount decimal(15,4);
ALTER TABLE dish_cost_card MODIFY COLUMN standard_cost decimal(15,4);
ALTER TABLE dish_cost_card MODIFY COLUMN actual_cost decimal(15,4);

-- ===== 2. 清理假数据 =====
DELETE FROM ingredient_purchase WHERE store_id=1;  -- 6条旧qty=0垃圾
DELETE FROM requisition_detail WHERE store_id=1;  -- 原料1/2/3
DELETE FROM requisition_order WHERE store_id=1;
DELETE FROM inventory_summary WHERE ingredient_id LIKE 'ING%' OR ingredient_id LIKE 'YC0__';  -- 旧ING001-005
DELETE FROM purchase_order_detail WHERE order_id NOT IN (SELECT order_id FROM purchase_order);  -- 15条孤儿
-- department去重: 删1-7旧编码(保留32-40新)
DELETE FROM department WHERE dept_id BETWEEN 1 AND 7 AND EXISTS(SELECT 1 FROM (SELECT dept_id FROM department WHERE dept_id BETWEEN 32 AND 40) d2);

-- ===== 3. unit_conversion 标准单位换算 =====
DELETE FROM unit_conversion WHERE store_id=1;

-- ===== 4. ingredient_cost_price 重算(采购单位+conversion_rate=克/采购单位+全精度净料单价) =====
DELETE FROM ingredient_cost_price WHERE store_id=1;

