-- ===== 6. dish_recipe AI生成(每菜按菜名+主料匹配原料+标准调味, 真实用量克) =====
DELETE FROM dish_recipe WHERE store_id=1;

-- ===== 7. dish_cost_card + detail (从配方汇总成本) =====
DELETE FROM dish_cost_card_detail WHERE store_id=1;
DELETE FROM dish_cost_card WHERE store_id=1;
SELECT NULL,1,r.dish_id,d.dish_name,d.dish_category,100.000,100.000,100.00,SUM(r.total_cost),SUM(r.total_cost),d.sale_price,ROUND((d.sale_price-SUM(r.total_cost))/d.sale_price*100,2),'active',NOW(),'成本会计'
FROM dish_recipe r JOIN dish_master d ON r.dish_id=d.dish_id WHERE r.store_id=1 GROUP BY r.dish_id,d.dish_name,d.dish_category,d.sale_price;
SELECT NULL,1,cc.cost_card_id,r.sort_order,r.ingredient_id,r.ingredient_name,(SELECT im.spec FROM ingredient_master im WHERE im.ingredient_id=r.ingredient_id),r.unit,r.quantity,r.quantity,r.quantity,r.net_unit_price,ROUND(r.quantity*r.net_unit_price,2),r.yield_rate,'标准配方' FROM dish_recipe r JOIN dish_cost_card cc ON r.dish_id=cc.dish_id WHERE r.store_id=1;

-- ===== 8. ingredient_cost_price 字段COMMENT =====
ALTER TABLE ingredient_cost_price MODIFY COLUMN cost_price_id bigint COMMENT '成本换算记录ID(主键)';
ALTER TABLE ingredient_cost_price MODIFY COLUMN store_id bigint COMMENT '门店ID(多租户隔离)';
ALTER TABLE ingredient_cost_price MODIFY COLUMN ingredient_id varchar(50) COMMENT '原料编码(FK→ingredient_master)';
ALTER TABLE ingredient_cost_price MODIFY COLUMN ingredient_name varchar(100) COMMENT '原料名称';
ALTER TABLE ingredient_cost_price MODIFY COLUMN purchase_unit varchar(20) COMMENT '采购单位(斤/只/袋/箱/桶/盘/瓶)';
ALTER TABLE ingredient_cost_price MODIFY COLUMN purchase_price decimal(15,8) COMMENT '采购单价(元/采购单位, Excel真实值全精度)';
ALTER TABLE ingredient_cost_price MODIFY COLUMN conversion_unit varchar(20) COMMENT '换算目标单位(克, 配方计价基准)';
ALTER TABLE ingredient_cost_price MODIFY COLUMN conversion_rate decimal(15,6) COMMENT '换算率(克/采购单位, 斤=500/袋=500/箱=6000)';
ALTER TABLE ingredient_cost_price MODIFY COLUMN yield_rate decimal(5,2) COMMENT '出成率%(净料率, 龙虾60/土豆88/净肉95)';
ALTER TABLE ingredient_cost_price MODIFY COLUMN net_price_per_unit decimal(15,8) COMMENT '净料单价(元/克=采购价÷换算率÷出成率%)';
ALTER TABLE ingredient_cost_price MODIFY COLUMN created_at timestamp COMMENT '创建时间';
ALTER TABLE ingredient_cost_price MODIFY COLUMN updated_at timestamp COMMENT '更新时间';

-- ===== 9. 验证 =====
SET FOREIGN_KEY_CHECKS=1;
SELECT '=== 价格精度验证(龙虾应0.03424) ===' AS info;
SELECT ingredient_name,purchase_unit,purchase_price,conversion_rate,yield_rate,net_price_per_unit FROM ingredient_cost_price WHERE ingredient_name LIKE '%龙虾%' OR ingredient_name='五花肉' OR ingredient_name='八角' OR ingredient_name='花甲' LIMIT 8;
SELECT '=== unit_conversion ===' AS info;
SELECT from_unit,to_unit,conversion_rate,category,description FROM unit_conversion WHERE store_id=1;
SELECT '=== 供应商关联 ===' AS info;
SELECT im.ingredient_category,COUNT(*) AS 原料数,sm.supplier_name FROM ingredient_master im LEFT JOIN supplier_master sm ON im.primary_supplier_id=sm.supplier_id WHERE im.store_id=1 GROUP BY im.ingredient_category,sm.supplier_name ORDER BY im.ingredient_category;
SELECT '=== dish_recipe配方 ===' AS info;
SELECT COUNT(*) AS 配方行数,COUNT(DISTINCT dish_id) AS 覆盖菜数 FROM dish_recipe WHERE store_id=1;
SELECT '=== 配方抽样(臭鳜鱼/红烧肉) ===' AS info;
SELECT dr.dish_id,dm.dish_name,dr.ingredient_name,dr.quantity,dr.unit_price,dr.total_cost,dr.yield_rate,dr.net_unit_price FROM dish_recipe dr JOIN dish_master dm ON dr.dish_id=dm.dish_id WHERE dr.store_id=1 AND (dm.dish_name LIKE '%臭鳜鱼%' OR dm.dish_name LIKE '%红烧%' OR dm.dish_name LIKE '%鱼%') ORDER BY dr.dish_id,dr.sort_order LIMIT 20;
SELECT '=== 成本卡 ===' AS info;
SELECT COUNT(*) AS 成本卡数,SUM(CASE WHEN standard_cost>0 THEN 1 ELSE 0 END) AS 有成本数 FROM dish_cost_card WHERE store_id=1;
SELECT '=== 成本卡抽样 ===' AS info;
SELECT cc.dish_id,cc.dish_name,cc.standard_cost,cc.selling_price,cc.gross_margin,(SELECT COUNT(*) FROM dish_cost_card_detail d WHERE d.cost_card_id=cc.cost_card_id) AS 明细数 FROM dish_cost_card cc WHERE cc.store_id=1 ORDER BY RAND() LIMIT 10;
SELECT '=== 假数据清理验证(应全0) ===' AS info;
SELECT 'ingredient_purchase' AS t,COUNT(*) FROM ingredient_purchase WHERE store_id=1 UNION ALL SELECT 'requisition_order',COUNT(*) FROM requisition_order WHERE store_id=1 UNION ALL SELECT '旧inventory',COUNT(*) FROM inventory_summary WHERE ingredient_id LIKE 'ING%' UNION ALL SELECT '孤儿明细',COUNT(*) FROM purchase_order_detail WHERE order_id NOT IN(SELECT order_id FROM purchase_order);
